package br.com.tapeteskalke.service;
import br.com.tapeteskalke.dto.*; import br.com.tapeteskalke.dto.ProdutoDtos.*; import br.com.tapeteskalke.entity.*; import br.com.tapeteskalke.exception.*; import br.com.tapeteskalke.repository.*; import java.math.*; import java.time.*; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class ProdutoService { private final ProdutoRepository repo; private final FornecedorRepository fornecedores; private final AuditService audit; private final CodigoService codigos; public ProdutoService(ProdutoRepository repo,FornecedorRepository fornecedores,AuditService audit,CodigoService codigos){this.codigos=codigos;this.repo=repo;this.fornecedores=fornecedores;this.audit=audit;}
 @Transactional(readOnly=true) public PageResponse<Response> list(String search,int page,int size){return PageResponse.from(repo.search(search==null?"":search.trim(),PageRequest.of(page,Math.min(Math.max(1,size),100),Sort.by("nome"))).map(this::response));}
 @Transactional(readOnly=true) public Response get(String id){return response(active(id));}
 @Transactional public Response create(Request r){var p=new Produto();copy(p,r);audit.created(p);return response(repo.save(p));}
 @Transactional public Response update(String id,Request r){var p=active(id);copy(p,r);audit.changed(p);return response(p);}
 @Transactional public void delete(String id){var p=active(id);p.setAtivo(false);p.setDeletedAt(OffsetDateTime.now(ZoneOffset.UTC));p.setDeletedBy(audit.userId());audit.changed(p);}
 public Produto active(String id){return repo.findById(id).filter(p->p.getDeletedAt()==null).orElseThrow(()->new ResourceNotFoundException("Produto",id));}
 public Produto locked(String id){return repo.lockActiveById(id).orElseThrow(()->new ResourceNotFoundException("Produto",id));}
 private void copy(Produto p,Request r){codigos.require(CodigoService.Tabela.TIPO_PRODUTO,r.tipo());codigos.require(CodigoService.Tabela.UNIDADE_MEDIDA,r.unidadeMedida());p.setNome(r.nome().trim());p.setTipo(r.tipo());p.setCategoria(r.categoria());p.setCor(r.cor());p.setTamanho(r.tamanho());p.setUnidadeMedida(r.unidadeMedida());p.setPodeSerVendido(r.podeSerVendido());p.setPodeSerMateriaPrima(r.podeSerMateriaPrima());p.setEstoqueMinimoComercial(or(r.estoqueMinimoComercial(),BigDecimal.ONE));p.setEstoqueMinimoProducao(or(r.estoqueMinimoProducao(),BigDecimal.ONE));p.setPrecoCusto(or(r.precoCusto(),BigDecimal.ZERO));p.setPrecoVenda(or(r.precoVenda(),BigDecimal.ZERO));p.setCodigoBarras(r.codigoBarras());p.setObservacoes(r.observacoes());p.setAtivo(r.ativo());p.setFornecedorPrincipal(r.fornecedorPrincipalId()==null||r.fornecedorPrincipalId().isBlank()?null:fornecedores.findById(r.fornecedorPrincipalId()).orElseThrow(()->new ResourceNotFoundException("Fornecedor",r.fornecedorPrincipalId())));}
 private BigDecimal or(BigDecimal v,BigDecimal d){return v==null?d:v;}
 public Response response(Produto p){return new Response(p.getId(),p.getNome(),p.getTipo(),p.getUnidadeMedida(),p.isPodeSerVendido(),p.isPodeSerMateriaPrima(),p.getEstoqueComercial(),p.getEstoqueProducao(),p.getEstoqueMinimoComercial(),p.getEstoqueMinimoProducao(),p.getPrecoVenda(),status(p.getEstoqueComercial(),p.getEstoqueMinimoComercial()),status(p.getEstoqueProducao(),p.getEstoqueMinimoProducao()),p.isAtivo(),p.getCategoria(),p.getCor(),p.getTamanho(),p.getPrecoCusto(),p.getCodigoBarras(),p.getFornecedorPrincipal()==null?null:p.getFornecedorPrincipal().getId(),p.getObservacoes());}
 private String status(BigDecimal saldo,BigDecimal minimo){return saldo.signum()==0?"ESGOTADO":saldo.compareTo(minimo)<=0?"BAIXO":"OK";}
}